// MUTATION_ONLY=<text> runs only the entries whose name contains it.
const selected = process.env.MUTATION_ONLY ? changes.filter(([name]) => name.includes(process.env.MUTATION_ONLY)) : changes;
let killed = 0;
try {
  for (const name of ['src', 'test', 'tools/e2e']) fs.cpSync(path.join(ROOT, name), path.join(work, name), { recursive: true });
  for (const name of ['package.json', 'config.json']) fs.copyFileSync(path.join(ROOT, name), path.join(work, name));
  fs.symlinkSync(path.join(ROOT, 'node_modules'), path.join(work, 'node_modules'), process.platform === 'win32' ? 'junction' : 'dir');
  for (const [name, file, before, after, testFile, pattern] of selected) {
    const original = fs.readFileSync(path.join(ROOT, file), 'utf8');
    assert.ok(original.includes(before), 'mutation anchor missing: ' + name);
    fs.writeFileSync(path.join(work, file), original.replace(before, after));
    try {
      const args = testFile ? ['--test', '--test-name-pattern=' + pattern, testFile] : ['tools/e2e/run.js'];
      // The end-to-end run alone takes about two minutes; unit tests far less.
      const result = spawnSync(process.execPath, args, { cwd: work, encoding: 'utf8', timeout: testFile ? 150000 : 360000,
        env: { ...process.env, SPAM_BOT_CONFIG: '', ANTHROPIC_API_KEY: '', ANTHROPIC_AUTH_TOKEN: '' } });
      assert.equal(result.error, undefined, name + ': execution error');
      assert.equal(result.signal, null, name + ': process was signalled');
      assert.notEqual(result.status, 0, 'SURVIVED: ' + name);
      assert.match(result.stdout + result.stderr, /AssertionError|ERR_ASSERTION|a busy chat must not reach the provider again/, name + ': must fail at an assertion');
      killed++;
      console.log('KILLED ' + name);
    } finally { fs.writeFileSync(path.join(work, file), original); }
  }
  console.log('MUTATION PASS: ' + killed + '/' + selected.length + ' killed' + (selected.length < changes.length ? ' (of ' + changes.length + ' entries)' : ''));
} finally {
  assert.equal(path.dirname(work), tempRoot);
  assert.ok(path.basename(work).startsWith('wa-guard-mutations-'));
  fs.rmSync(work, { recursive: true, force: true });
}
